//! Ports of Go's regexp/syntax tests (parse_test.go, simplify_test.go,
//! prog_test.go); tables are generated by tools/regexp/gen_fixtures.py.
use rust_stdlib::regexp::syntax::*;

#[allow(dead_code)]
#[path = "fixtures/regexp_tables.rs"]
mod tables;
use tables::syntax as t;

const TEST_FLAGS: Flags = Flags(Flags::MATCH_NL.0 | Flags::PERL_X.0 | Flags::UNICODE_GROUPS.0);

fn op_name(op: Op) -> Option<&'static str> {
    Some(match op {
        Op::NO_MATCH => "no",
        Op::EMPTY_MATCH => "emp",
        Op::LITERAL => "lit",
        Op::CHAR_CLASS => "cc",
        Op::ANY_CHAR_NOT_NL => "dnl",
        Op::ANY_CHAR => "dot",
        Op::BEGIN_LINE => "bol",
        Op::END_LINE => "eol",
        Op::BEGIN_TEXT => "bot",
        Op::END_TEXT => "eot",
        Op::WORD_BOUNDARY => "wb",
        Op::NO_WORD_BOUNDARY => "nwb",
        Op::CAPTURE => "cap",
        Op::STAR => "star",
        Op::PLUS => "plus",
        Op::QUEST => "que",
        Op::REPEAT => "rep",
        Op::CONCAT => "cat",
        Op::ALTERNATE => "alt",
        _ => return None,
    })
}

/// Go's parse_test.go `dump`.
fn dump(re: &Regexp) -> String {
    let mut b = String::new();
    dump_into(&mut b, re);
    b
}

fn dump_into(b: &mut String, re: &Regexp) {
    match op_name(re.op) {
        None => b.push_str(&format!("op{}", re.op.0)),
        Some(name) => match re.op {
            Op::STAR | Op::PLUS | Op::QUEST | Op::REPEAT => {
                if re.flags.contains(Flags::NON_GREEDY) {
                    b.push('n');
                }
                b.push_str(name);
            }
            Op::LITERAL => {
                b.push_str(if re.rune.len() > 1 { "str" } else { "lit" });
                if re.flags.contains(Flags::FOLD_CASE)
                    && re
                        .rune
                        .iter()
                        .any(|&r| rust_stdlib::unicode::simple_fold(r) != r)
                {
                    b.push_str("fold");
                }
            }
            _ => b.push_str(name),
        },
    }
    b.push('{');
    match re.op {
        Op::END_TEXT => {
            if !re.flags.contains(Flags::WAS_DOLLAR) {
                b.push_str("\\z");
            }
        }
        Op::LITERAL => {
            for &r in &re.rune {
                b.push(char::from_u32(r as u32).unwrap_or('\u{fffd}'));
            }
        }
        Op::CONCAT | Op::ALTERNATE => re.sub.iter().for_each(|s| dump_into(b, s)),
        Op::STAR | Op::PLUS | Op::QUEST => dump_into(b, &re.sub[0]),
        Op::REPEAT => {
            b.push_str(&format!("{},{} ", re.min, re.max));
            dump_into(b, &re.sub[0]);
        }
        Op::CAPTURE => {
            if !re.name.is_empty() {
                b.push_str(&re.name);
                b.push(':');
            }
            dump_into(b, &re.sub[0]);
        }
        Op::CHAR_CLASS => {
            let parts: Vec<String> = re
                .rune
                .chunks(2)
                .map(|p| {
                    if p[0] == p[1] {
                        format!("{:#x}", p[0])
                    } else {
                        format!("{:#x}-{:#x}", p[0], p[1])
                    }
                })
                .collect();
            b.push_str(&parts.join(" "));
        }
        _ => {}
    }
    b.push('}');
}

fn parse_dump(tests: &[(&str, &str)], flags: Flags) {
    for &(pat, want) in tests {
        let re = parse(pat, flags).unwrap_or_else(|e| panic!("Parse({pat:?}): {e}"));
        if want.is_empty() {
            continue;
        }
        assert_eq!(dump(&re), want, "Parse({pat:?}).Dump()");
    }
}

#[test]
fn parse_simple() {
    parse_dump(t::PARSE_TESTS, TEST_FLAGS);
    parse_dump(t::FOLDCASE_TESTS, Flags::FOLD_CASE);
    parse_dump(t::LITERAL_TESTS, Flags::LITERAL);
    parse_dump(t::MATCHNL_TESTS, Flags::MATCH_NL);
    parse_dump(t::NOMATCHNL_TESTS, Flags(0));
}

#[test]
fn invalid_and_dialect_regexps() {
    let mut invalid: Vec<Vec<u8>> = t::INVALID_REGEXPS.iter().map(|s| s.to_vec()).collect();
    invalid.push([b"(".repeat(1000), b")".repeat(1000)].concat());
    invalid.push([b"(?:".repeat(1000), b")*".repeat(1000)].concat());
    invalid.push([b"(".to_vec(), b"(xx?)".repeat(1000), b"){1000}".to_vec()].concat());
    invalid.push(b"(xx?){1000}".repeat(1000));
    invalid.push(br"\pL".repeat(27000));
    for re in &invalid {
        assert!(
            parse_bytes(re, Flags::PERL).is_err(),
            "Perl {:?}",
            String::from_utf8_lossy(re)
        );
        assert!(
            parse_bytes(re, Flags::POSIX).is_err(),
            "POSIX {:?}",
            String::from_utf8_lossy(re)
        );
    }
    for re in t::ONLY_PERL {
        assert!(parse_bytes(re, Flags::PERL).is_ok(), "{re:?}");
        assert!(parse_bytes(re, Flags::POSIX).is_err(), "{re:?}");
    }
    for re in t::ONLY_POSIX {
        assert!(parse_bytes(re, Flags::PERL).is_err(), "{re:?}");
        assert!(parse_bytes(re, Flags::POSIX).is_ok(), "{re:?}");
    }
}

#[test]
fn to_string_equivalent_parse() {
    for &(pat, want) in t::PARSE_TESTS {
        let re = parse(pat, TEST_FLAGS).unwrap();
        if want.is_empty() {
            continue;
        }
        let s = re.to_string();
        if s != pat {
            let nre = parse(&s, TEST_FLAGS).unwrap_or_else(|e| panic!("{pat:?} -> {s:?}: {e}"));
            assert_eq!(dump(&nre), dump(&re), "{pat:?} -> {s:?}");
            assert_eq!(nre.to_string(), s);
        }
    }
}

#[test]
fn string_tests() {
    for &(pat, want) in t::STRING_TESTS {
        assert_eq!(
            parse(pat, Flags::PERL).unwrap().to_string(),
            want,
            "{pat:?}"
        );
    }
}

#[test]
fn simplify_tests() {
    let flags = Flags(Flags::MATCH_NL.0 | (Flags::PERL.0 & !Flags::ONE_LINE.0));
    for &(pat, want) in t::SIMPLIFY_TESTS {
        let re = parse(pat, flags).unwrap_or_else(|e| panic!("Parse({pat:?}): {e}"));
        assert_eq!(re.simplify().to_string(), want, "Simplify({pat:?})");
    }
}

#[test]
fn compile_tests() {
    for &(pat, want) in t::COMPILE_TESTS {
        let re = parse(pat, Flags::PERL).unwrap();
        let p = compile(&re).unwrap();
        assert_eq!(p.to_string(), want, "compiled {pat:?}");
    }
}

#[test]
fn constants_and_messages() {
    assert_eq!(Flags::PERL.0, 4 | 16 | 64 | 128);
    assert_eq!(Flags::MATCH_NL, Flags::CLASS_NL | Flags::DOT_NL);
    assert_eq!(Op::ALTERNATE.to_string(), "Alternate");
    assert_eq!(Op(200).to_string(), "Op(200)");
    assert_eq!(InstOp::RUNE_ANY_NOT_NL.to_string(), "InstRuneAnyNotNL");
    assert_eq!(InstOp(99).to_string(), "");
    let e = parse("a**", Flags::PERL).unwrap_err();
    assert_eq!(e.code, ErrorCode::INVALID_REPEAT_OP);
    assert_eq!(
        e.to_string(),
        "error parsing regexp: invalid nested repetition operator: `**`"
    );
    assert_eq!(
        parse_bytes(b"\xff", Flags::PERL).unwrap_err().code,
        ErrorCode::INVALID_UTF8
    );
    assert_eq!(
        parse("(a", Flags::PERL).unwrap_err().code,
        ErrorCode::MISSING_PAREN
    );
    let deep = format!("{}a{}", "(".repeat(1001), ")".repeat(1001));
    assert_eq!(
        parse(&deep, Flags::PERL).unwrap_err().code,
        ErrorCode::NESTING_DEPTH
    );
}

#[test]
fn empty_op_context_and_word_chars() {
    let ctx = empty_op_context(-1, 'a' as i32);
    assert!(ctx.0 & EmptyOp::BEGIN_TEXT.0 != 0 && ctx.0 & EmptyOp::WORD_BOUNDARY.0 != 0);
    assert!(is_word_char('_' as i32) && !is_word_char('-' as i32));
}

#[test]
fn cap_names_and_equal() {
    let re = parse("(a)(?P<n>b)", Flags::PERL).unwrap();
    assert_eq!(re.max_cap(), 2);
    assert_eq!(re.cap_names(), ["", "", "n"]);
    assert!(re.equal(&parse("(a)(?P<n>b)", Flags::PERL).unwrap()));
    assert!(!re.equal(&parse("(a)(b)", Flags::PERL).unwrap()));
}
